-- Tags: no-parallel
-- no-parallel: rewrite rules are global server state

-- The operands of a `PARALLEL WITH` produced by the result template of a rule are generated by the rule,
-- not written by the user, so the rules are not applied to them again. Otherwise a rule whose result
-- contains the matched statement would keep rewriting the first operand into the same `PARALLEL WITH`.

DROP RULE IF EXISTS rule_05480;
CREATE RULE rule_05480 AS (DROP TABLE IF EXISTS t_05480_a)
REWRITE TO (DROP TABLE IF EXISTS t_05480_a PARALLEL WITH DROP TABLE IF EXISTS t_05480_b);

CREATE TABLE t_05480_a (x UInt8) ENGINE = Memory;
CREATE TABLE t_05480_b (x UInt8) ENGINE = Memory;

SET query_rules = 'rule_05480';
DROP TABLE IF EXISTS t_05480_a;
SET query_rules = '';

SELECT count() FROM system.tables WHERE database = currentDatabase() AND name LIKE 't_05480_%';

-- The operands written by the user are still matched: the rewritten operand is executed once as well.
CREATE TABLE t_05480_a (x UInt8) ENGINE = Memory;
CREATE TABLE t_05480_b (x UInt8) ENGINE = Memory;
CREATE TABLE t_05480_c (x UInt8) ENGINE = Memory;

SET query_rules = 'rule_05480';
DROP TABLE IF EXISTS t_05480_c PARALLEL WITH DROP TABLE IF EXISTS t_05480_a;
SET query_rules = '';

SELECT count() FROM system.tables WHERE database = currentDatabase() AND name LIKE 't_05480_%';

DROP RULE rule_05480;
